-- WP-13 tests FIRST; all fixtures, roles and pgTAP roll back.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_catalog;
grant usage on schema extensions to wedding_mutator;
select no_plan();
insert into auth.users(id,email) values ('13000000-0000-4000-8000-000000000001','wp13-sql-a@example.invalid'),('13000000-0000-4000-8000-000000000002','wp13-sql-b@example.invalid');
create temporary table wp13(label text primary key,id uuid);
grant select,insert,update on wp13 to authenticated,wedding_mutator;
create temporary table wp13_before(version text,events bigint,completed timestamptz);
grant select,insert,update on wp13_before to authenticated;
create function pg_temp.task_change(p_label text,p_operation text,p_changes jsonb default '{}',p_confirm boolean default false,p_override boolean default false) returns jsonb language plpgsql security invoker as $f$
 begin return public.update_task((select id from wp13 where label='wedding'),(select id from wp13 where label=p_label),(select state_version from public.weddings where id=(select id from wp13 where label='wedding')),p_operation,p_changes,p_confirm,p_override); end;
$f$;
select ok(to_regprocedure('public.update_task(uuid,uuid,text,text,jsonb,boolean,boolean)') is not null,'narrow task operation exists');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"13000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into wp13 values('wedding',public.create_wedding('WP13 SQL synthetic','Test city'));
select public.save_draft_setup((select id from wp13 where label='wedding'),(select state_version from public.weddings),'WP13 SQL synthetic','Test city',null,true,null,'[{"title":"Reception"}]');
select public.generate_draft((select id from wp13 where label='wedding'),(select state_version from public.weddings));
insert into wp13 select 'root',id from public.tasks where template_key='shared.invite-wording.v1';
insert into wp13 select 'child',id from public.tasks where template_key='shared.invite-review.v1';
insert into wp13 select 'leaf',id from public.tasks where template_key='shared.invite-send.v1';
insert into wp13 select 'free',id from public.tasks where template_key='shared.accessibility.v1';
select throws_ok($$select pg_temp.task_change('free','status','{"status":"IN_PROGRESS"}')$$,'55000',null,'ACTIVE operation not allowed in DRAFT');
select public.activate_plan((select id from wp13 where label='wedding'),(select state_version from public.weddings),true);
select lives_ok($$select pg_temp.task_change('free','status','{"status":"IN_PROGRESS"}')$$,'normal TO_DO to IN_PROGRESS');
select is((select status from public.tasks where id=(select id from wp13 where label='free')),'IN_PROGRESS','status persists in real database');
select lives_ok($$select pg_temp.task_change('free','details','{"title":"Synthetic detail","owner_name":"Parent","due_date":null}')$$,'offline owner and missing due allowed');
select is((select owner_name from public.tasks where id=(select id from wp13 where label='free')),'Parent','named owner persists without account');
select is((select due_date from public.tasks where id=(select id from wp13 where label='free')),null::date,'unknown due remains NULL');
select lives_ok($$select pg_temp.task_change('free','details','{"title":"Synthetic detail","owner_name":"Parent","due_date":"2027-02-14"}')$$,'calendar due date update');
select is((select due_date::text from public.tasks where id=(select id from wp13 where label='free')),'2027-02-14','date-only preserved');
insert into wp13_before select state_version,(select count(*) from public.audit_events),null from public.weddings;
select throws_ok($$select pg_temp.task_change('child','status','{"status":"COMPLETED"}')$$,'23514',null,'blocked completion requires override');
select is((select state_version from public.weddings),(select version from wp13_before),'failed override leaves version unchanged');
select is((select count(*) from public.audit_events),(select events from wp13_before),'failed override leaves audit unchanged');
select is((select status from public.tasks where id=(select id from wp13 where label='child')),'TO_DO','failed override leaves task unchanged');
select lives_ok($$select pg_temp.task_change('child','status','{"status":"COMPLETED","confirmed_by":"Reported by relative to coordinator"}',false,true)$$,'explicit blocked completion supported');
select ok((select completed_at is not null and status_confirmed_at is not null and status_confirmed_by='Reported by relative to coordinator' from public.tasks where id=(select id from wp13 where label='child')),'completion and separate confirmation metadata recorded');
select is((select count(*) from public.audit_events where entity_id=(select id from wp13 where label='child') and action='TASK_COMPLETION_OVERRIDE'),1::bigint,'override audited once');
select is((select status from public.tasks where id=(select id from wp13 where label='root')),'TO_DO','override does not complete prerequisite');
select is((select status from public.tasks where id=(select id from wp13 where label='leaf')),'TO_DO','override does not complete dependent');
select throws_ok($$select pg_temp.task_change('child','details','{"title":"Review","due_date":"2028-01-01"}')$$,'23514',null,'completed due date cannot silently move');
select lives_ok($$select pg_temp.task_change('child','details','{"title":"Review retained","owner_name":"Sibling"}')$$,'completed title/owner update preserves completion');
select ok((select status='COMPLETED' and completed_at is not null from public.tasks where id=(select id from wp13 where label='child')),'completed record remains completed');
select throws_ok($$select pg_temp.task_change('child','status','{"status":"TO_DO"}')$$,'23514',null,'reopening completed needs confirmation');
select lives_ok($$select pg_temp.task_change('child','status','{"status":"TO_DO"}',true)$$,'confirmed reopening supported');
select ok((select completed_at is null and status_confirmed_at is null and status_confirmed_by is null from public.tasks where id=(select id from wp13 where label='child')),'confirmed reopen clears current timestamps only');
select ok(exists(select 1 from public.audit_events where entity_id=(select id from wp13 where label='child') and action='TASK_COMPLETION_OVERRIDE' and before_after->'after'->>'completed_at' is not null),'historical completion retained in audit');
select lives_ok($$select pg_temp.task_change('root','status','{"status":"DEFERRED"}')$$,'deferral supported');
select throws_ok($$select pg_temp.task_change('root','status','{"status":"COMPLETED"}')$$,'23514',null,'DEFERRED cannot skip resume');
select throws_ok($$select pg_temp.task_change('child','status','{"status":"COMPLETED"}')$$,'23514',null,'deferred prerequisite still blocks');
select lives_ok($$select pg_temp.task_change('root','status','{"status":"TO_DO"}')$$,'deferred resumes TO_DO');
select throws_ok($$select pg_temp.task_change('root','archive','{}',true)$$,'23514',null,'incomplete prerequisite with retained child cannot archive');
select lives_ok($$select pg_temp.task_change('root','status','{"status":"COMPLETED"}')$$,'ready root completion');
select lives_ok($$select pg_temp.task_change('child','status','{"status":"COMPLETED"}')$$,'completed prerequisite unlocks normal completion');
update wp13_before set version=(select state_version from public.weddings),events=(select count(*) from public.audit_events),completed=(select completed_at from public.tasks where id=(select id from wp13 where label='child'));
select lives_ok($$select pg_temp.task_change('child','status','{"status":"COMPLETED"}')$$,'same status retry does not rewrite completion');
select is((select state_version from public.weddings),(select version from wp13_before),'same-status no-op does not bump version');
select is((select count(*) from public.audit_events),(select events from wp13_before),'same-status no-op does not duplicate audit');
select is((select completed_at from public.tasks where id=(select id from wp13 where label='child')),(select completed from wp13_before),'original current completion timestamp preserved');
select throws_ok($$select pg_temp.task_change('root','archive','{}',true)$$,'23514',null,'completed prerequisite cannot archive');
select throws_ok($$select pg_temp.task_change('leaf','archive')$$,'22023',null,'archive requires confirmation');
select lives_ok($$select pg_temp.task_change('leaf','archive','{}',true)$$,'unlinked incomplete leaf may archive');
select ok((select archived_at is not null and prerequisite_task_id=(select id from wp13 where label='child') from public.tasks where id=(select id from wp13 where label='leaf')),'archive retains identity and dependency');
select throws_ok($$select pg_temp.task_change('leaf','status','{"status":"IN_PROGRESS"}')$$,'55000',null,'archived task cannot update');
select throws_ok($$select pg_temp.task_change('leaf','details','{"title":"Hidden edit"}')$$,'55000',null,'archived task details frozen');
select lives_ok($$select pg_temp.task_change('free','status','{"status":"TO_DO"}')$$,'IN_PROGRESS returns TO_DO');
select throws_ok($$select public.update_task((select id from wp13 where label='wedding'),(select id from wp13 where label='free'),'0','status','{"status":"IN_PROGRESS"}',false,false)$$,'40001',null,'stale version rejected');
select throws_ok($$select pg_temp.task_change('free','status','{"status":"BLOCKED"}')$$,'22023',null,'BLOCKED never stored');
select throws_ok($$select pg_temp.task_change('free','details','{"title":"x","prerequisite_task_id":null}')$$,'22023',null,'dependency injection rejected');
select throws_ok($$update wedding_private.tasks set status='COMPLETED',completed_at=now() where id=(select id from wp13 where label='free')$$,'42501',null,'ordinary direct DML denied');
select throws_ok($$delete from wedding_private.tasks where id=(select id from wp13 where label='child')$$,'42501',null,'completed/history hard delete denied');
select throws_ok($$delete from wedding_private.audit_events where entity_id=(select id from wp13 where label='child')$$,'42501',null,'audit hard delete denied');
set local role wedding_mutator;
select throws_ok($$update wedding_private.tasks set prerequisite_task_id=id where id=(select id from wp13 where label='free')$$,'23514',null,'DB self prerequisite denied');
select throws_ok($$update wedding_private.tasks set prerequisite_task_id=(select id from wp13 where label='child') where id=(select id from wp13 where label='root')$$,'23514',null,'DB A to B to A cycle denied');
select throws_ok($$update wedding_private.tasks set title='hidden edit' where id=(select id from wp13 where label='leaf')$$,'23514',null,'DB archived task is immutable');
select throws_ok($$do $chain$ declare parent uuid:=(select id from wp13 where label='free'); next_id uuid; begin for n in 1..65 loop insert into wedding_private.tasks(wedding_id,title,prerequisite_task_id) values((select id from wp13 where label='wedding'),'Synthetic chain',parent) returning id into next_id; parent:=next_id; end loop; end $chain$ $$,'23514',null,'DB traversal stops beyond64 ancestors');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"13000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.update_task((select id from wp13 where label='wedding'),(select id from wp13 where label='free'),'0','status','{"status":"COMPLETED"}',false,true)$$,'42501',null,'B cannot change A task');
select is((select count(*) from public.tasks),0::bigint,'B cannot read A task records');
select ok(not has_function_privilege('anon','public.update_task(uuid,uuid,text,text,jsonb,boolean,boolean)','EXECUTE'),'anonymous operation denied');
select ok(not has_table_privilege('authenticated','wedding_private.tasks','UPDATE'),'no broad client update grant');
insert into wp13 values('b-wedding',public.create_wedding('WP13 B synthetic','Test city'));
insert into wp13 values('b-task',public.add_draft_task((select id from wp13 where label='b-wedding'),(select state_version from public.weddings),null,'B private task',null,null,null));
select set_config('request.jwt.claims','{"sub":"13000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.update_task((select id from wp13 where label='wedding'),(select id from wp13 where label='b-task'),(select state_version from public.weddings),'status','{"status":"COMPLETED"}',false,true)$$,'42501',null,'existing B task cannot be forged under A parent');
select lives_ok($$select public.update_task((select id from wp13 where label='wedding'),null,(select state_version from public.weddings),'add','{"title":"Manual active task","owner_name":"Parent","due_date":null,"ceremony_id":null}',false,false)$$,'active manual shared task can be added');
select ok(exists(select 1 from public.tasks where title='Manual active task' and owner_name='Parent' and due_date is null and prerequisite_task_id is null),'active manual task persists without dependency');
select * from finish();
rollback;
